<?php require __DIR__.'/../app.php';if(!bb_user_id()) bb_redirect('login.php');$id=bb_user_id();$user=bb_one('SELECT * FROM users WHERE user_id=?','i',[$id]);$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
try{bb_check_csrf();$action=$_POST['action'] ?? '';
if($action==='recovery'){if(!password_verify($_POST['current_password'] ?? '',$user['password'])) throw new InvalidArgumentException('Current password is incorrect.');bb_schema();$_SESSION['recovery_code']=bb_recovery($id);bb_redirect('recovery.php');}
if($action==='password'){$new=$_POST['new_password'] ?? '';if(!password_verify($_POST['current_password'] ?? '',$user['password'])) throw new InvalidArgumentException('Current password is incorrect.');if(strlen($new)<12||strlen($new)>72||$new!==($_POST['confirm_password'] ?? '')) throw new InvalidArgumentException('New passwords must match and contain 12–72 characters.');$hash=password_hash($new,PASSWORD_DEFAULT);bb_query('UPDATE users SET password=? WHERE user_id=?','si',[$hash,$id]);$_SESSION['auth_hash']=hash('sha256',$hash);session_regenerate_id(true);$success='Password updated.';}
elseif($action==='profile'){
$first=trim($_POST['first_name'] ?? '');$last=trim($_POST['last_name'] ?? '');$username=trim($_POST['username'] ?? '');$email=trim($_POST['email'] ?? '');$phone=trim($_POST['phone'] ?? '');
if($first===''||$last===''||strlen($first)>100||strlen($last)>100) throw new InvalidArgumentException('Enter your first and last name.');
if(!preg_match('/^[a-zA-Z0-9_\-]{3,50}$/D',$username)||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>255||strlen($phone)>50) throw new InvalidArgumentException('Enter a valid username, email and phone.');
if(bb_one('SELECT user_id FROM users WHERE user_id<>? AND (email=? OR username=?)','iss',[$id,$email,$username])) throw new InvalidArgumentException('That email or username is already registered.');
if($email!==$user['email']&&!password_verify($_POST['current_password'] ?? '',$user['password'])) throw new InvalidArgumentException('Enter your current password to change your email.');
$picture=$user['profile_picture'];$newFile=null;
if(($_FILES['profile_picture']['error'] ?? UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$f=$_FILES['profile_picture'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>2*1024*1024) throw new InvalidArgumentException('Upload an image smaller than 2 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/gif'=>'gif','image/webp'=>'webp'][$mime] ?? null;if(!$ext||!getimagesize($f['tmp_name'])) throw new InvalidArgumentException('Upload a JPG, PNG, GIF or WebP image.');$directory=__DIR__.'/../uploads/profile_pictures';if(!is_dir($directory)) mkdir($directory,0755,true);$picture=bin2hex(random_bytes(16)).'.'.$ext;$newFile=$directory.'/'.$picture;if(!move_uploaded_file($f['tmp_name'],$newFile)) throw new RuntimeException('Upload failed.');}
try{bb_query('UPDATE users SET first_name=?,last_name=?,username=?,email=?,phone=?,profile_picture=? WHERE user_id=?','ssssssi',[$first,$last,$username,$email,$phone,$picture,$id]);}catch(Throwable $e){if($newFile) unlink($newFile);throw $e;}
$_SESSION['user']=$username;$success='Profile updated.';
}elseif($action!=='password') throw new InvalidArgumentException('Unknown action.');
$user=bb_one('SELECT * FROM users WHERE user_id=?','i',[$id]);
}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){error_log($e->getMessage());$error='Could not update your profile. Please try again.';}
}
?>
